import {MultiSiteProvider} from '@salesforce/retail-react-app/app/contexts';
import {CheckoutProvider} from '@salesforce/retail-react-app/app/pages/checkout/util/checkout-context';
import {ServerContext} from '@salesforce/pwa-kit-react-sdk/ssr/universal/contexts';
import {expect, within} from 'storybook/test';
import Payment from './payment';

/*
 * The Payment partial wraps an Adyen drop-in inside a ToggleCard. In Storybook:
 * - CheckoutProvider starts with step=undefined (no basket or customer), so the card
 *   renders in collapsed/not-editing state — useCheckout().step !== STEPS.PAYMENT.
 * - AdyenCheckout is guarded by `authToken && basket`, neither of which resolves here,
 *   so the Adyen drop-in never mounts and there are no third-party network calls.
 *
 * Needs the full commerce provider stack so CheckoutProvider's own hook calls
 * (useCurrentBasket, useCurrentCustomer, useEinstein, useSFPaymentsEnabled, etc.)
 * do not throw. CommerceApiProvider uses disableAuthInit so no real SFCC auth runs.
 *
 * ServerContext.Provider: CheckoutProvider → useSFPaymentsEnabled → useAppOrigin →
 * useOrigin(), which unconditionally destructures `{res}` from useServerContext()
 * before its own browser-vs-server branch runs. An empty object is sufficient —
 * `res` resolves to undefined, but useOrigin short-circuits on `typeof window !== 'undefined'`
 * before touching `res.locals`. Same pattern as header/index.stories.tsx.
 */

const storybookQueryClient = new QueryClient({
    defaultOptions: {queries: {retry: false, refetchOnWindowFocus: false}},
});

const meta: Meta<typeof Payment> = {
    title: 'Pages/CheckoutPayment',
    component: Payment,
    decorators: [
        (Story) => (
            <ServerContext.Provider value={{}}>
                <MemoryRouter>
                    <MultiSiteProvider
                        site={{id: 'ZimmermannAU', alias: 'au'}}
                        locale={{id: 'en-AU', alias: 'en-AU'}}
                        buildUrl={(path: string) => path}
                    >
                        <QueryClientProvider client={storybookQueryClient}>
                            <CommerceApiProvider
                                clientId="00000000-0000-0000-0000-000000000000"
                                organizationId="f_ecom_storybook_001"
                                shortCode="storybook"
                                siteId="ZimmermannAU"
                                locale="en-AU"
                                currency="AUD"
                                proxy="https://storybook.invalid/mobify/proxy/api"
                                redirectURI="https://storybook.invalid/callback"
                                disableAuthInit
                                silenceWarnings
                            >
                                <CheckoutProvider>
                                    <Story />

